// Contrasts a HEAVY per-request gateway with a LEAN one (cache + async + no blocking I/O).
package com.bank.gateway.demo;

import java.util.logging.*;

public class LeanGatewayDemo {
    private static final Logger log = Logger.getLogger("LeanGateway");
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setLevel(Level.ALL); h.setFormatter(new LgLogFormatter());
        log.addHandler(h); log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        KeyService keyService = new KeyService();
        int requests = 20;

        log.info("=== HEAVY gateway: per-request key fetch + synchronous logging ===");
        HeavyGateway heavy = new HeavyGateway(keyService);
        long t1 = System.currentTimeMillis();
        for (int i = 0; i < requests; i++) heavy.handle("valid-token");
        long e1 = System.currentTimeMillis() - t1;
        log.info(() -> "HEAVY total=" + e1 + "ms networkKeyFetches=" + heavy.getKeyFetches()
                + " syncLogWrites=" + heavy.getLogWrites());

        log.info("=== LEAN gateway: cached key + async batched logging + no blocking I/O ===");
        AsyncAuditLogger asyncLogger = new AsyncAuditLogger();
        LeanGateway lean = new LeanGateway(keyService, asyncLogger);
        long t2 = System.currentTimeMillis();
        for (int i = 0; i < requests; i++) lean.handle("valid-token");
        long e2 = System.currentTimeMillis() - t2;
        asyncLogger.flush();
        log.info(() -> "LEAN total=" + e2 + "ms networkKeyFetches=" + lean.getKeyFetches()
                + " (logging moved off hot path)");
        asyncLogger.shutdown();
    }
}

