// Simulates fetching JWT signing keys over the network (expensive).
class KeyService {
    String fetchSigningKey() {
        sleep(15); // network round trip to the auth server's JWKS endpoint
        return "RS256-public-key";
    }
    private void sleep(long ms) { try { Thread.sleep(ms); } catch (InterruptedException e) { Thread.currentThread().interrupt(); } }
}

