class HeavyGateway {
    private static final Logger log = Logger.getLogger("LeanGateway");
    private final KeyService keyService;
    private int keyFetches = 0; private int logWrites = 0;
    HeavyGateway(KeyService keyService) { this.keyService = keyService; }

    void handle(String token) {
        // BAD: fetch the signing key over the network on EVERY request.
        String key = keyService.fetchSigningKey(); keyFetches++;
        verify(token, key);                         // CPU: crypto verification
        // BAD: synchronous blocking log write on the hot path.
        writeLogSync();                             logWrites++;
        // (then route to backend...)
    }
    private boolean verify(String token, String key) { return token.startsWith("valid"); }
    private void writeLogSync() { try { Thread.sleep(5); } catch (InterruptedException e) { Thread.currentThread().interrupt(); } } // blocking I/O
    int getKeyFetches() { return keyFetches; }
    int getLogWrites() { return logWrites; }
}

