class LeanGateway {
    private static final Logger log = Logger.getLogger("LeanGateway");
    private final KeyService keyService;
    private final AsyncAuditLogger asyncLogger;
    private volatile String cachedKey;          // cache expensive, repeatable work
    private int keyFetches = 0;
    LeanGateway(KeyService keyService, AsyncAuditLogger asyncLogger) {
            this.keyService = keyService;
            this.asyncLogger = asyncLogger;
    }

    void handle(String token) {
        // GOOD: fetch the key ONCE and cache it; subsequent requests pay nothing.
        if (cachedKey == null) { cachedKey = keyService.fetchSigningKey(); keyFetches++; }
        verify(token, cachedKey);               // only the cheap crypto remains on the path
        // GOOD: hand logging to an async batched sink — never block the request.
        asyncLogger.log("request served");
        // GOOD: downstream call would be non-blocking with a timeout (not shown)
    }
    private boolean verify(String token, String key) { return token.startsWith("valid"); }
    int getKeyFetches() { return keyFetches; }
}

