class AsyncAuditLogger {
    private static final Logger log = Logger.getLogger("LeanGateway");
    private final java.util.concurrent.BlockingQueue<String> queue = new java.util.concurrent.LinkedBlockingQueue<>();
    private final java.util.concurrent.ExecutorService worker = java.util.concurrent.Executors.newSingleThreadExecutor();
    private volatile boolean running = true;
    AsyncAuditLogger() {
        worker.submit(() -> {
            java.util.List<String> batch = new java.util.ArrayList<>();
            while (running || !queue.isEmpty()) {
                String item = queue.poll();
                if (item != null) batch.add(item);
                if (batch.size() >= 10) { flushBatch(batch); batch.clear(); }
            }
            if (!batch.isEmpty()) flushBatch(batch);
        });
    }
    // enqueue is near-instant; the request never waits for the write.
    void log(String msg) { queue.offer(msg); }
    private void flushBatch(java.util.List<String> batch) { log.fine(() -> "async flushed " + batch.size() + " log lines off hot path"); }
    void flush() { try { Thread.sleep(50); } catch (InterruptedException e) { Thread.currentThread().interrupt(); } }
    void shutdown() { running = false; worker.shutdown(); }
}

